            print("Phuong trinh co 1 nghiem x = 0")
        else:
            x = -c / b
            print("Phuong trinh co 1 nghiem x = ", x)
else:
    delta = b ** 2 - 4 * a * c
    if delta < 0:
        print("Phuong trinh vo nghiem!")
    elif delta == 0:
        x = -b / (2 * a)
        print("Phuong trinh co 1 nghiem x = ", x)
    else:
        print("Phuong trinh co 2 nghiem phan biet!")
        x1 = float((-b - sqrt(delta)) / (2 * a))
